#!/usr/bin/env bash
set -euo pipefail

usage() {
  echo "usage: $0 START END (times as HH:MM)"
}

(( $# == 2 )) || { usage >&2; exit 64; }
start=$1
end=$2
zcat -f access.log.1.gz access.log |
  awk -v start="$start" -v end="$end" '
    {t = substr($4, 14, 5)}
    t >= start && t < end && $9 >= 500 {n[t]++}
    END {for (m in n) print m, n[m]}' |
  sort

