#!/usr/bin/env bash
set -euo pipefail

awk '{print $NF}' access.log | sort -n | awk '
  {a[NR] = $1}
  END {
    print "requests", NR
    print "p50", a[int((NR * 50 + 99) / 100)]
    print "p95", a[int((NR * 95 + 99) / 100)]
    print "max", a[NR]
  }'
awk '{s += $NF} END {printf "avg %.3f\n", s / NR}' access.log

#!/usr/bin/env bash
set -euo pipefail

awk '$7 ~ /^\/api\// {print $7, $NF}' access.log | sort -k2,2n | awk '
  {n[$1]++; t[$1, n[$1]] = $2; sum[$1] += $2}
  END {
    for (p in n) {
      if (n[p] >= 20) {
        printf "%s %d avg %.3f p50 %s max %s\n", p, n[p], sum[p] / n[p], t[p, int((n[p] * 50 + 99) / 100)], t[p, n[p]]
      }
    }
  }' | sort

