#!/usr/bin/env bash
set -euo pipefail

awk '{print $7, $NF}' access.log | sort -k2,2n | awk '
  {n[$1]++; t[$1, n[$1]] = $2}
  END {
    for (p in n) {
      if (n[p] >= 20) {
        print p, n[p], t[p, int((n[p] * 50 + 99) / 100)], t[p, int((n[p] * 95 + 99) / 100)], t[p, n[p]]
      }
    }
  }' | sort -k4,4nr -k1,1 | head -n 5
